from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
s=s.replace('BOK War Room V0.8.7 — 2026','BOK War Room V0.9.0 — 2026',1)
s=s.replace('APP V0.8.7','APP V0.9.0',1)
# Add nav tab before Results.
anchor='<button data-view="results">Results</button>'
if anchor not in s: raise SystemExit('results nav anchor missing')
s=s.replace(anchor,'<button data-view="publishing">Publishing</button>\n    '+anchor,1)
# Add lightweight publishing styles before </style>.
styles='''\n.publishGrid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.publishOutput{white-space:pre-wrap;line-height:1.55;background:#fff8f1;border:1px solid var(--line);border-radius:12px;padding:14px;font-size:13px;min-height:120px}.copyRow{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.publishTable{width:100%;min-width:760px}.publishTable th{position:static}@media(max-width:900px){.publishGrid{grid-template-columns:1fr}}\n'''
s=s.replace('</style>',styles+'</style>',1)
# Insert section before Results.
section='''\n<section id="publishing" class="view">\n  <div class="hero">\n    <div class="panel"><div class="panelhead orange"><h2>Publishing Center</h2><span id="publishWeekTag">Week 1</span></div><div class="pad rules">One frozen BOK dataset, ready for the site and newsletter. Outputs below are generated only from the active week's V3.0 card and staff ledger; they do not change model inputs or grading.</div></div>\n    <div class="panel"><div class="panelhead"><h3>Output Status</h3></div><div class="pad" id="publishStatus"></div></div>\n  </div>\n  <div class="panel tablewrap"><div class="panelhead"><h2>Game Week Model Table</h2><button class="btn ghost" data-copy="publishTableText">Copy Table</button></div><table class="publishTable"><thead><tr><th>Game</th><th>BOK Fair Line</th><th>Frozen Splash</th><th>Official Pick</th><th>Edge</th></tr></thead><tbody id="publishGameRows"></tbody></table><textarea id="publishTableText" style="position:absolute;left:-9999px"></textarea></div>\n  <div class="publishGrid" style="margin-top:18px">\n    <div class="panel"><div class="panelhead orange"><h3>Texas Model Copy</h3><button class="btn ghost" data-copy="publishTexasCopy">Copy</button></div><div class="pad"><div class="publishOutput" id="publishTexasCopy"></div></div></div>\n    <div class="panel"><div class="panelhead"><h3>Model Card Summary</h3><button class="btn ghost" data-copy="publishModelCopy">Copy</button></div><div class="pad"><div class="publishOutput" id="publishModelCopy"></div></div></div>\n    <div class="panel"><div class="panelhead"><h3>Staff Picks Summary</h3><button class="btn ghost" data-copy="publishStaffCopy">Copy</button></div><div class="pad"><div class="publishOutput" id="publishStaffCopy"></div></div></div>\n    <div class="panel"><div class="panelhead"><h3>Newsletter Analytics Block</h3><button class="btn ghost" data-copy="publishNewsletterCopy">Copy</button></div><div class="pad"><div class="publishOutput" id="publishNewsletterCopy"></div></div></div>\n  </div>\n  <div class="footerNote">Publishing Center is deterministic and data-only. Editorial voice, predictions beyond V3.0 margin, projected scores, and win probabilities remain separate unless explicitly added under a separately defined methodology.</div>\n</section>\n\n'''
res='<section id="results" class="view">'
if res not in s: raise SystemExit('results section anchor missing')
s=s.replace(res,section+res,1)
# Add renderer before renderResults.
fn='''\nfunction copyPublish(id){\n  const el=document.getElementById(id); if(!el)return;\n  const text=('value' in el?el.value:el.textContent)||'';\n  if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text);\n  else{const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove();}\n}\nfunction renderPublishing(){\n  const wk=currentWeek(),games=currentGames();\n  const tag=document.getElementById('publishWeekTag'); if(!tag)return; tag.textContent='Week '+wk.week;\n  const status=document.getElementById('publishStatus');\n  status.innerHTML=`<b>${wk.locked?'LOCKED OFFICIAL CARD':'PRELIMINARY CARD'}</b><br><span class="mini">${games.length} games · ${wk.meta?.snapshotDate||BASE.meta.snapshotDate} model snapshot · Splash ${wk.meta?.splashLock||BASE.meta.splashLock}</span>`;\n  document.getElementById('publishGameRows').innerHTML=games.map(g=>`<tr><td class="game">${gameName(g)}</td><td>${g['BOK Fair Line']}</td><td>${splashText(g)}</td><td class="pick">${g['ATS Pick']}</td><td>${Number(g['Model Edge']).toFixed(1)}</td></tr>`).join('');\n  document.getElementById('publishTableText').value=['Game\\tBOK Fair Line\\tFrozen Splash\\tOfficial Pick\\tEdge',...games.map(g=>`${gameName(g)}\\t${g['BOK Fair Line']}\\t${splashText(g)}\\t${g['ATS Pick']}\\t${Number(g['Model Edge']).toFixed(1)}`)].join('\\n');\n  const tx=games.find(g=>g.Away==='Texas'||g.Home==='Texas'),tr=ratings.find(r=>r.Team==='Texas');\n  if(tx&&tr){const opp=tx.Away==='Texas'?tx.Home:tx.Away,or=ratings.find(r=>r.Team===opp)||{};document.getElementById('publishTexasCopy').textContent=`BOK Model V3.0 makes ${tx['BOK Fair Line']} for Texas vs. ${opp}, compared with the frozen Splash line of ${splashText(tx)}. The official ATS pick is ${tx['ATS Pick']}, a ${Number(tx['Model Edge']).toFixed(1)}-point model edge. Texas is V3 #${tr['V3 Rank']} (${Number(tr['V3 Rating']).toFixed(1)}); ${opp} is #${or['V3 Rank']} (${Number(or['V3 Rating']).toFixed(1)}).`; } else document.getElementById('publishTexasCopy').textContent='Texas is not on the active BOK slate.';\n  const sorted=[...games].sort((a,b)=>Number(b['Model Edge'])-Number(a['Model Edge'])),top=sorted[0],five=games.filter(g=>Number(g['Model Edge'])>=5).length,avg=games.reduce((a,g)=>a+Number(g['Model Edge']),0)/Math.max(1,games.length);\n  document.getElementById('publishModelCopy').textContent=`BOK V3.0 Week ${wk.week}: ${games.length} games on the frozen card. Largest model edge: ${gameName(top)} — ${top['ATS Pick']} (${Number(top['Model Edge']).toFixed(1)} points). ${five} edge${five===1?'':'s'} of 5.0+ points. Average absolute edge: ${avg.toFixed(1)} points.`;\n  const picks=(wk.staffPicks||wk.picks||[]);\n  if(picks.length){const people=[...new Set(picks.map(p=>p.person||p.staff||p.name).filter(Boolean))];document.getElementById('publishStaffCopy').textContent=`Week ${wk.week} staff ledger: ${picks.length} picks entered across ${people.length} staff member${people.length===1?'':'s'}${people.length?': '+people.join(', '):''}.`; } else document.getElementById('publishStaffCopy').textContent=`Week ${wk.week} staff picks have not been entered into the active week ledger yet.`;\n  document.getElementById('publishNewsletterCopy').textContent=`BOK MODEL — WEEK ${wk.week}\\n${games.length}-game frozen card | V3.0: 80% standardized SP+ + 20% roster talent | HFA: 2.5 points (0 neutral)\\nTop edge: ${top['ATS Pick']} (${Number(top['Model Edge']).toFixed(1)}) in ${gameName(top)}. ${five} play${five===1?'':'s'} at 5+ model points. Texas: ${tx?tx['ATS Pick']+' ('+Number(tx['Model Edge']).toFixed(1)+')':'not on active slate'}.`;\n  document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copyPublish(b.dataset.copy));\n}\n\n'''
anchor2='function renderResults(){'
if anchor2 not in s: raise SystemExit('renderResults anchor missing')
s=s.replace(anchor2,fn+anchor2,1)
# Ensure global render path refreshes publishing whenever renderAll runs. Find renderAll body call sequence.
if 'renderPublishing();' not in s:
    # safest insert immediately before renderResults call occurrence in renderAll-like code, using last common call string if found
    needle='renderResults();renderAutopsy();'
    if needle in s: s=s.replace(needle,'renderPublishing();renderResults();renderAutopsy();')
# Also nav click render may not rerender; initialize once by app boot via existing renderAll. If still absent, append call before closing script.
if 'renderPublishing();' not in s: raise SystemExit('could not wire renderPublishing')
p.write_text(s,encoding='utf-8')
print('V0.9 Publishing Center applied')
